import{_ as a,o,c as t,a2 as r}from"./chunks/framework.VjMZkWOe.js";const u=JSON.parse('{"title":"Contratos e handoff","description":"","frontmatter":{},"headers":[],"relativePath":"contratos.md","filePath":"contratos.md"}'),d={name:"contratos.md"};function i(s,e,n,c,p,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="contratos-e-handoff" tabindex="-1">Contratos e handoff <a class="header-anchor" href="#contratos-e-handoff" aria-label="Permalink to &quot;Contratos e handoff&quot;">​</a></h1><h2 id="referencia-executavel" tabindex="-1">Referência executável <a class="header-anchor" href="#referencia-executavel" aria-label="Permalink to &quot;Referência executável&quot;">​</a></h2><p>A API usa REST JSON em <code>/v1</code>. Schemas TypeBox definem entrada, DTOs e OpenAPI; o cliente TypeScript deve consumir o artefato gerado pela entrega, não reproduzir tipos manualmente. O <a href="/grande-ganho-docs/openapi.json">OpenAPI JSON desta entrega</a> registra métodos, parâmetros e schemas das rotas implementadas; a <a href="./telas.html">matriz de telas</a> distingue a API confirmada das capacidades futuras. Esse contrato não comprova implantação cloud ou capacidade de carga.</p><p>Gerar o contrato com <code>npm run contracts:generate</code> antes de <code>npm run docs:build</code>. O JSON público é uma cópia explícita do contrato gerado; nenhuma outra saída de build ou fonte privada é copiada com ele. A API também fornece <code>/v1/openapi.json</code> conforme sua política de autenticação.</p><p>Não há documentação pública de dados reais, URLs internas, IDs de projetos ou credenciais. Exemplos abaixo são sintéticos e descrevem semântica; não são respostas capturadas de produção.</p><h2 id="semantica-de-dados" tabindex="-1">Semântica de dados <a class="header-anchor" href="#semantica-de-dados" aria-label="Permalink to &quot;Semântica de dados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Conceito</th><th>Contrato</th></tr></thead><tbody><tr><td>Organização</td><td>Obtida da sessão/associação, nunca confiada ao payload</td></tr><tr><td>Pessoa</td><td>Cadastro dentro da organização; pode participar de vários programas</td></tr><tr><td>Matrícula</td><td>Participação específica, com ciclo, responsáveis, programa e estado</td></tr><tr><td>Turma/carteira</td><td>Turma agrupa programa; carteira organiza responsabilidade</td></tr><tr><td>Datas</td><td>Instantes UTC ISO 8601; exibição com timezone IANA, padrão <code>America/Sao_Paulo</code></td></tr><tr><td>Data civil</td><td>Campo <code>YYYY-MM-DD</code> para dia sem instante, quando o schema assim define</td></tr><tr><td>Dinheiro</td><td>Unidade menor como string inteira e moeda, por exemplo <code>&quot;123450&quot;</code>, <code>&quot;BRL&quot;</code></td></tr><tr><td>Score</td><td>Opcional; zero é valor conhecido, ausência é desconhecido</td></tr><tr><td>Avaliação</td><td>Fonte, autor, <code>observed_at</code>, frescor, visibilidade, sensibilidade e evidência</td></tr><tr><td>Progresso</td><td>Concluídas/elegíveis; canceladas excluídas; denominador zero desconhecido</td></tr><tr><td>Restrição</td><td>Resposta remove valores e existência quando necessário</td></tr><tr><td>Versão</td><td>Mutações usam a versão lida; conflito exige releitura</td></tr></tbody></table><p>Data observada e data registrada são diferentes: a primeira diz quando o fato ocorreu; a segunda quando foi recebido. O frontend não calcula frescor usando apenas a hora em que baixou a resposta. Progresso conhecido de <code>0%</code> não deve virar &quot;Sem plano&quot;.</p><h2 id="listas-e-falhas" tabindex="-1">Listas e falhas <a class="header-anchor" href="#listas-e-falhas" aria-label="Permalink to &quot;Listas e falhas&quot;">​</a></h2><p>Paginação por cursor, limite máximo e ordenações em allowlist. O cursor pertence à consulta e ao escopo atual; mudar filtro exige reiniciar a paginação. Filtros desconhecidos devem ser rejeitados ou tratados conforme schema, nunca concatenados a SQL. Campo de ordenação não define permissão.</p><p>Erros são estruturados e têm código estável, mensagem segura e identificador de requisição. Detalhes de SQL, stack, concessões ocultas, conteúdo pessoal e nomes de arquivos privados não entram na resposta. O schema gerado é a autoridade do formato exato.</p><table tabindex="0"><thead><tr><th>Condição</th><th>Tratamento do cliente</th></tr></thead><tbody><tr><td>Entrada inválida</td><td>Corrigir campos; conservar o rascunho local não sensível</td></tr><tr><td>Sessão expirada/revogada</td><td>Limpar dados e solicitar autenticação novamente</td></tr><tr><td>Permissão negada</td><td>Remover a ação; não insistir com outro tenant ou papel</td></tr><tr><td>Registro não visível</td><td>Tratar resposta segura sem revelar existência</td></tr><tr><td>Versão conflitante</td><td>Recarregar e pedir reconciliação explícita do usuário</td></tr><tr><td>Chave idempotente conflitante</td><td>Corrigir fluxo; não repetir payload diferente com mesma chave</td></tr><tr><td>Limite de requisições</td><td>Respeitar espera e aplicar backoff com limite</td></tr><tr><td>Erro transitório</td><td>Repetir somente leitura ou mutação com idempotência adequada</td></tr></tbody></table><h2 id="idempotencia-e-concorrencia" tabindex="-1">Idempotência e concorrência <a class="header-anchor" href="#idempotencia-e-concorrencia" aria-label="Permalink to &quot;Idempotência e concorrência&quot;">​</a></h2><p>Uma intenção de usuário recebe uma <code>Idempotency-Key</code>; tentativas da mesma intenção reutilizam a chave e payload. Uma nova intenção usa outra chave. Não gerar outra chave automaticamente quando a rede cair depois do envio: o servidor pode ter confirmado a mutação.</p><p>O contrato informa operações idempotentes e validade da chave. Mudanças concorrentes usam <code>version</code>. A UI não resolve conflito por &quot;último clique vence&quot;. O cliente pode oferecer comparação entre versão atual e rascunho, mas a decisão precisa ser explícita.</p><h2 id="upload-e-evidencia" tabindex="-1">Upload e evidência <a class="header-anchor" href="#upload-e-evidencia" aria-label="Permalink to &quot;Upload e evidência&quot;">​</a></h2><p>Evidência passa por autorização, limite de bytes, allowlist de tipos e quarentena. Extensão e <code>Content-Type</code> informados pelo cliente não provam conteúdo. Malware deve ser inspecionado antes de servir o objeto; estado pendente ou recusado nunca gera download válido.</p><p>Não guardar URL de objeto como autorização permanente. O backend reavalia escopo e concessão ao servir. Se o mecanismo real for URL temporária, sua janela de exposição precisa estar documentada e ser curta; para conteúdo pessoal revogável, streaming autenticado é preferível. Remover evidência inclui objeto, metadados e caches autorizados.</p><h2 id="android-online-e-web" tabindex="-1">Android online e web <a class="header-anchor" href="#android-online-e-web" aria-label="Permalink to &quot;Android online e web&quot;">​</a></h2><p>O primeiro Android é online e usa a mesma API do desktop. Não há APK nem sincronização offline nesta entrega. A camada de autenticação armazena bearer opaco em recurso nativo seguro; tokens de identidade não ficam em logs de depuração.</p><p>Web usa cookie seguro com CSRF nas mutações e origem/CORS restritos. O frontend não lê o cookie <code>HttpOnly</code>. Troca de organização, logout e revogação invalidam consultas e caches. Conteúdo pessoal não entra em service worker, analytics, crash report ou notificações de tela bloqueada.</p><p>Estados obrigatórios: carregando, vazio, desconhecido, desatualizado, erro recuperável, acesso recusado, sessão expirada, conflito e job pendente/falho. Tabelas grandes usam paginação; detalhes só carregam quando necessários. Acessibilidade: nomes de campos, foco preservado, erro associado ao campo, navegação por teclado e texto além de cor.</p><h2 id="futuras-capacidades" tabindex="-1">Futuras capacidades <a class="header-anchor" href="#futuras-capacidades" aria-label="Permalink to &quot;Futuras capacidades&quot;">​</a></h2><p>IA deverá preservar fontes e revisão humana, sem extrair nota pessoal de transcrição como fato. WhatsApp exige integração oficial, consentimento/finalidade e política de retenção; não usar sessão pessoal ou scraping. Networking exige controle sobre exposição de contato. Encantamento exige aprovação humana de compra e orçamento. Portal do mentorado exige escopo de titular distinto do papel de equipe.</p><p>Push, iOS e offline têm contratos próprios de privacidade e sincronização. Só entram quando autorizados e implementados; a existência do backend não significa autorização de disponibilizar dados a aplicativos externos.</p>',25)])])}const h=a(d,[["render",i]]);export{u as __pageData,h as default};
